L42_1 = "Thus ends one ill-fated relationship, giving way for yet another long festering feud to surface."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_6_INTERLUDE_3"
L43_1 = "Ye King of Birds, bereft of head and thy wings broken! How then is the view from the ground instead? Surely it differ from watching thy previously exalted station. Ascend to the altar, once thou hast decided. For she shall await with breath bated with bellows for thy arrival."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_6_INTERLUDE_2"
L44_1 = "The Society swiftly and covertly expanded its forces. Despite the organization's desperate attempts to stop them, it did not always accomplish its strategic objectives. In fact, it had to endure several critical losses."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_6_INTERLUDE_1"
L45_1 = "Research to determine the properties of artifacts continue with the utmost discretion across the globe today. However, no technology must strive to exploit and amplify such properties."
L43_1[1] = L44_1
L43_1[2] = L45_1
