L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_6_1_HM"
L49_1 = "Until the day the conductor takes the stage, the orchestra will not cease its symphony of apocalypse."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_6_1"
L50_1 = "Amongst the dead, the survivors. Amongst the survivors, the suffering. And amongst them, the weepers. And behind them, the cowering. And in front of them, the laughing. Ha Ha. Hee Hee. Ho Ho. They go on laughing. "
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_5_INTERLUDE_1"
L51_1 = "It has been confirmed that a significant amount of land recently purchased by Jehuty Biotech once belonged to the Replacer Syndicate. There are concerns that Jehuty may be attempting to collude with remaining Syndicate members, or appropriating Syndicate technology."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_5_2"
L52_1 = "By securing the legacy plans of the Future-at-War initiative, discontinued after the war, the Future-at-War Foundation secured its hegemony over the defense industry. Despite the relatively low volume, their sale of more affordable, mass-produced Titans to City Management added to such standing."
L50_1[1] = L51_1
L50_1[2] = L52_1
