L28_1 = "SI_PF_POPUP_EVENT_RACE_BETTING_TUTORIAL"
L29_1 = [[
<b><color=#4EC2F3>[Team Relay]</color></b>
<color=#FFCF3B>- Select one of the two teams to root for with Sneakers.</color>
<color=#FFCF3B>- If the team you selected wins, you can obtain the reward according to the reward multiplier.</color>
<color=#FFCF3B>- Races are held once per day, and you will not be able to participate during the settling period.</color>

<b><color=#FFFFFF>[Race Missions]</color></b>
<color=#F2F2F2>- Clear the provided missions to earn Sneakers.</color>

<b><color=#FFFFFF>[Cheering]</color></b>
<color=#F2F2F2>- Use Sneakers to root for the team you selected.</color>
<color=#F2F2F2>- You can only choose one team per day.</color>
<color=#F2F2F2>- You can use up to 500 Sneakers per day.</color>

<b><color=#FFFFFF>[Reward]</color></b>
<color=#F2F2F2>- If the team you selected wins, Sneakers as a reward will be distributed in accordance with the reward multiplier.</color>
<color=#F2F2F2>- If your team loses, 80% of Sneakers used for cheering will be returned.</color>
<color=#F2F2F2>- You can receive the rewards for the races you've participated in when the next day's race starts.</color>]]
L27_1[1] = L28_1
L27_1[2] = L29_1
