L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JUNIOR_C_POLEARM_RA"
L6_1 = "Unexpected powers that appeared out of nowhere forced a once-happy girl to face hardship. She avoided making friends out of fear that her powers would harm them, and she confined herself to gardening to suppress her powers. But after realizing that the powers she despised could help those in need and her friends, she decided to stop hiding them. Even though she is not yet a true hero, she is working hard to become the person that everyone wants her to be."
L4_1[1] = L5_1
L4_1[2] = L6_1
