L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_INTERLUDE3"
L14_1 = "The Gordias Division was required for our ancestors to settle in the Normalside. To take back the world they once flourished in among gods, the Gordias Division aimed to fight alongside the Administration and stop doomsday."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_INTERLUDE1"
L15_1 = "The Family Alliance was established with the lead of the Nanahara family, who worshiped snakes. Their existence served as repentance for humanity who betrayed god."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_INTERLUDE5"
L16_1 = "The countless wounds on the Nether God’s body were already battered by the dark poison from the Plague God. \nKnowing that his soul would also be tainted if left untreated... The Nether God called together his three descendants."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_INTERLUDE4"
L17_1 = "The Afterlife is our cross to bear, for we live on in the Normalside. Do not deny it. Do not forget it. No matter how much time passes."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "BC_NANAHARA2_3_NAME"
L18_1 = "Reaching the Ultimate"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_INTERLUDE2"
L19_1 = "Protecting the estate was far from an easy task. The most important goal was to keep our secret hidden from the Normalside outside of the estate."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
