L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_3_4"
L21_1 = "Only misdirection awaits a god's soul awakened by hollowness."
L19_1[1] = L20_1
L19_1[2] = L21_1
