L28_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_2_1_HM"
L29_1 = "Baba Yaga generates Corruption rays to disrupt the radar network. While ideas such as this are considered taboo in the Normalside, the technology of the Northern Union is highly developed in certain areas... up to an abnormal level."
L27_1[1] = L28_1
L27_1[2] = L29_1
