L30_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_CONNECT_LIFETIME"
L31_1 = "I'm Jia, your fairy who will lead you to the future. Shall we go then, sir?"
