L29_1[2] = L31_1
L30_1 = {}
L31_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_TOUCH_NORMAL_1"
L32_1 = "Yes. Grandfather’s methods were wrong. But I believe his wishes weren’t all lies. So that’s why I'm going to carry on my grandfather's legacy in the right way."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_TOUCH_NORMAL_2"
L33_1 = "When you say I look like a fairy, you mean that Jia twinkles and catches your eye, right? Then I'll light up the dark road ahead and allow people to travel to a brighter future."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA@AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_LOBBY_TOUCH_NORMAL_3"
L34_1 = "I don't want people to refer to me by a grand name like Singularity. Hmm? Ho ho, oh you. Becoming President of a company was merely inheriting the family business."
