L46_1 = "SI_PF_GAUNTLET_POPUP_LEAGUEINFO_INFO"
L47_1 = "· Weekly ranks are settled on every Sunday at 11:00 p.m.\n· You will receive a reward, depending on your performance in the last week.\n· Weekly leagues begin on Mondays at 4:00 a.m."
L45_1[1] = L46_1
