L19_1 = "SI_PALACE_NAME_SUB_01"
L20_1 = "The monsters born out of our fears waylay intruders and block their escape. They know what happens to the stranded in the end. "
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_PALACE_NAME_SUB_02"
L21_1 = "This Palace doesn't need steep walls around it. The monsters that walk out of the shadows on the horizon can never be completely destroyed, and they multiply in countless numbers."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_PALACE_NAME_SUB_03"
L22_1 = "Dangerous monsters lurk in the shadows. They ruthlessly punish intruders in their Palace, each with a single swipe of their hand."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_PALACE_NAME_SUB_04"
L23_1 = "The shadows cast over this land feed on the despair of intruders and give birth to impregnable shapes and forms. Those who impatiently enter the land, wildly swinging weapons, only nurture them further."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_PALACE_NAME_SUB_05"
L24_1 = "The shadows pooling deep inside the place rise and fall ominously. You'd better stop the wind, or a storm will roll in and swallow everything."
