L1_1 = {}
L2_1 = "SI_BOSS_DESC_01"
L3_1 = "A massive weapon of unknown origin from outside our dimension. It specializes in pulverizing approaching enemies, and is also capable of unsupported dimension jumps thanks to an engine system similar to a dimensional ship's.\n\nIt may have been originally programmed to travel to and from the Counterside hunting C.O.s, but by the time it was discovered, it was out of control, having been damaged beyond repair by Corruption Rays.\n\n<color=#FFCF3B>※ The Moderator receives additional damage when attacked in the rear, where it is vulnerable.</color>"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_BOSS_DESC_02"
L4_1 = "A massive weapon of unknown origin from outside our dimension. It specializes in subduing distant enemies, and is also capable of unsupported dimension jumps thanks to an engine system similar to a dimensional ship's.\n\nIt may have been originally programmed to travel to and from the Counterside hunting C.O.s, but by the time it was discovered, it was out of control, having been damaged beyond repair by Corruption Rays.\n\n<color=#FFCF3B>※ The Moderator receives additional damage when attacked in the rear, where it is vulnerable.</color>"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_BOSS_DESC_03"
L5_1 = "A Shadow in the hyperdepths of the Counterside. She hates every living thing and revels in hunting down those that run from her. A creature of the warped world, she's not bound by time or space, and is always threatening the Normalside beyond the walls.\n\n<color=#FFCF3B>※ Nervier and Monolith specialize in fighting Ground units.</color>"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_BOSS_DESC_04"
L6_1 = "A noble being that has numerous sisters on the Counterside. Neither a Corrupted Object nor a Shadow, she's been freed from the eternal tether of fate and become one with the warped world, attaining immortality along the way. She's smarter than any human and stronger than any Shadow, but her arrogance may be her undoing.\n\n<color=#FFCF3B>※ Defeat Sollicitatio before she reaches your ship.\nYou can use Tower units to temporarily distract her.</color>"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_BOSS_DESC_05"
L7_1 = "A Category 3 C.O. observed regardless of the depth.\nUnlike the Beast type, which is dominated by instinct, it has the discretion to wait for an opportunity, thus posing a greater threat.\nIts combat style changes greatly depending on the armament floating around its main body.\n\n<color=#FFCF3B>※ Attack with units with multiple-hit skills\nto interrupt Tyrant Armor's attack patterns.</color>"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_BOSS_DESC_06"
L8_1 = "A Category 3 C.O. observed regardless of the depth.\nUnlike the Beast type, which is dominated by instinct, it has the discretion to wait for an opportunity, thus posing a greater threat.\nIts combat style changes greatly depending on the armament floating around its main body.\n\n<color=#FFCF3B>※ Minimize the damage by decreasing\nthe number of units within Tyrant Sword's range.</color>"
L6_1[1] = L7_1
L6_1[2] = L8_1
