L37_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP@AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP_GET_01"
L38_1 = "Finally... I have arrived in this world... Very well. To save our world from falling apart, and to survive... We will now join you in the front lines. Administrator."
