L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP@AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP_LOBBY_CONNECT"
L40_1 = "While it's nice to be relaxed, don't you think there are too many papers that require your attention, Administrator?"
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP@AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP_LOBBY_CONNECT_LIFETIME"
L41_1 = "The coffee here is much more fragrant than the ones from our world. Would you like a cup as well, Administrator?"
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP@AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP_LOBBY_TOUCH_NORMAL_1"
L42_1 = "The lives of soldiers in the field depend on the commander. It is the commander's duty to assess the battlefield under any circumstances."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP@AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP_LOBBY_TOUCH_NORMAL_2"
L43_1 = "The Delta Seven members in this world are different people from the members in mine. So even if I do meet them... I will not be swayed."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP@AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP_LOBBY_TOUCH_NORMAL_3"
L44_1 = "Budget management is an important task within an organization. So please, Administrator, refrain from making any spontaneous purchases in the–... What's this? The newest Alphatrix dishwasher? W-would you mind if I touch it?"
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP@AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP_LOBBY_TOUCH_NORMAL_4"
L45_1 = "Even if the world ends tomorrow... Even if our path ends as a dead end... We will still fight. A future that our fallen comrades could not see… we have a duty to watch it to the end."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP@AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP_LOBBY_TOUCH_LIFETIME_1"
L46_1 = "The reason why my hair is turning white is the side effects of my Unique Gear. While there's not much discomfort, if you feel uneasy about it... Huh? It looks good...? O-oh... I mean... Thank you."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP@AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP_LOBBY_TOUCH_LIFETIME_2"
L47_1 = "It's good that I can now process many thoughts at once, but on the other hand, there are now more things to worry about. Come to think of it... Administrator, your jacket button is loose. Take it off so I can fix it for you."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP@AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP_LOBBY_TOUCH_LIFETIME_3"
L48_1 = "This eye is directly connected to the system of Aegis. I can call in the ship whenever I want. What do you say, Administrator? Would you like to go on a ride?"
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP@AB_UI_UNIT_VOICE_NKM_UNIT_DELTA_CA_KYLE_AP_LOBBY_TOUCH_LIFETIME_4"
L49_1 = "The most baffling thing I found in this world... is the TV series, \"The Bridge of Seduction\". How could they possibly air something so lewd and promiscuous...? What? It's also a novel?"
L47_1[1] = L48_1
L47_1[2] = L49_1
