L2_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR_LOBBY_CONNECT"
L3_1 = "I was cleaning up the office a bit. Don't mind me, it's just my hobby."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR_LOBBY_CONNECT_LIFETIME"
L4_1 = "Morning coffee's the best. When I was at the Institution, a certain someone kept making me drink black tea."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR_LOBBY_TOUCH_NORMAL_1"
L5_1 = "I heard this suit was what my grandfather used to wear when he was in the Old Administration. I don't know if I'm fit to be wearing this, but... you know. It's up to me to decide from now on, right?"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR_LOBBY_TOUCH_NORMAL_2"
L6_1 = "It's not easy to wield a shield and stand in front of everyone. Because if I fall, those behind me will be exposed to danger. In that regard, Little Captain Félicette is truly amazing."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR_LOBBY_TOUCH_NORMAL_3"
L7_1 = "Why do I carry around rubber gloves? I saw a stain over there, and I'll be bothered all day if I don't take care of it. You have some detergent in the supply storage, right? Also, do you think I can borrow a toothbrush you don't use?"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR@AB_UI_UNIT_VOICE_NKM_UNIT_BD_C_ROI_PR_LOBBY_TOUCH_NORMAL_4"
L8_1 = "Doesn't matter to me if you call me by my first or family name. Class doesn't come from the name but from one's actions. Or at least that's what Morgan told me..."
L6_1[1] = L7_1
