L30_1 = {}
L31_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_GET_01"
L32_1 = "So much changed while I was asleep. Well then, will you keep me company to talk about some age-old stories, Administrator?"
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_CAPTAIN"
L33_1 = "Fu fuu, leave it to me. I'm used to these kinds of tasks."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_CONNECT"
L34_1 = "Oh, you're here. I was making carrot salad. Do you want to try some? Hmm. You shouldn't be too picky."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_CONNECT_LIFETIME"
L35_1 = "I was looking around the company. I saw some familiar faces. Guess your reputation is better than I thought, huh?"
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_NORMAL_1"
L36_1 = "Do not think I like carrots just because I'm a bunny. I preferred vegetables over meat, even before my awakening. Fu fuu, the gym rat Commander would frown whenever she saw me eat."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_NORMAL_2"
L37_1 = "I inherited the name Swift from Commander Lionel when I was young. He used to rally and lead Bygones, including myself. He was like a father to my compatriots and me."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_NORMAL_3"
L38_1 = "I'm sorry, but could you not stare at my ears like that? It's embarrassing because my ears unconsciously perk up whenever I hear something."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_NORMAL_4"
L39_1 = "I saw that someone named Lee Sooyeon is the Vice President of this company. Is that... the same Lee Sooyeon that I know? It is? Oh, I couldn't tell. She's become a lot more mature."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_LIFETIME_1"
L40_1 = "Bunny girl? So, you're into that kind of stuff. No wonder the Administration's official PR uniform is a bunny girl outfit. Hmm, but I won't need that headband. Having four giant ears would look weird, don't you think?"
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_LIFETIME_2"
L41_1 = "So much has changed. Things that were kept secret before are now common knowledge. My Bygone compatriots no longer have to hide themselves. How interesting."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_RABBIT_LOBBY_TOUCH_LIFETIME_3"
L42_1 = "I heard that Justine struggled alone while I was frozen. I'm still the same while she grew up to become an adult. Fu fuu, I wonder what Alice would've thought if she saw Justine now."
L40_1[1] = L41_1
L40_1[2] = L42_1
