L30_1 = {}
L31_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_GET_01"
L32_1 = "Your causal calculator must have finally permitted my cooperation. I am Felix, the Northern Union's Chief of the General Staff. But you can address me by name when it's just us two. And I'll call you Boss."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_CAPTAIN"
L33_1 = "Don't feel pressured. You're used to using people, aren't you?"
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_CONNECT"
L34_1 = "What am I listening to? It's the Brandenburg Concerto. G major calms the mind, you see."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_CONNECT_LIFETIME"
L35_1 = "I was listening to the music you recommended. You have good taste."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_1"
L36_1 = "Death is followed by rest. We have a responsibility to restore order among the suffering Shadows. However, we must also respect their unwavering loyalty even after death. Like my Shadows, and the Shadow that you care for."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_2"
L37_1 = "I'm in a position of authority that forces me to be hostile to your Administration. However, I do not intend to slander and harass you in private. Rather, I want to help. For you can't go down in vain."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_3"
L38_1 = "Have you ever held the hand of a dying soldier? The sight of a cold, trembling hand clinging so desperately... is something one cannot forget in mere days. It's quite effective when you need to straighten your mind."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_4"
L39_1 = "One deep breath is enough to become determined to end a person. And yet, here we are, sitting across the table from one another and enjoying tea. I guess it means... that today's not the day."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_LIFETIME_1"
L40_1 = "Getting rid of me won't be that difficult. I don't lock my bedroom or even place a guard in front. So... you can show me your true colors at any time. Fu fuu."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_LIFETIME_2"
L41_1 = "My hobby is collecting feathers. I even have a few from birds that went extinct. The beauty of retaining color and form even after death is... special, in my opinion. I want to show them to you."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_LIFETIME_3"
L42_1 = "The higher your hopes are, the more devastating the fall is. So, don't feel burdened by my assistance. I only wish that you keep raising your hopes."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_LIFETIME_4"
L43_1 = "People think that nothing is impossible for my army, but that's not true. Look at how long it took me to get one person's attention... and have him call out my name."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_WORLDMAP_CHECK"
L44_1 = "Something feels missing. Maybe I should hang up some of my collection?"
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_WORLDMAP_MISSION_START"
L45_1 = "You like the way I work?"
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_WORLDMAP_MISSION_COMPLETE"
L46_1 = "I never choose the losing side."
