L2_1[2] = L4_1
L3_1 = {}
L4_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_GET_01"
L5_1 = "My name is Robin Fitzwater, a knight-errant who protects the weak and brings about justice. Oh, loyal one of the Administration, become my squire and stand by my side in service...! H-how was that? Did I sound like a knight just now?"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_CAPTAIN"
L6_1 = "I just have to stand over here?"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_CONNECT"
L7_1 = "You're always so diligent. I should be more like you."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_CONNECT_LIFETIME"
L8_1 = "Hello, Squire. Good morning, is it not?"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_NORMAL_1"
L9_1 = "One must show confidence in order to earn trust from others. That's why I'm learning a lot from Ms. Aura. Like her lines that leave a strong impression... or even her cool poses."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_NORMAL_2"
L10_1 = "I have a lot of flaws. I'm a pushover and can't really refuse anything. But I guess that helps me gain courage when I'm around Ms. Aura."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_NORMAL_3"
L11_1 = "Ms. Aura likes to lay on the grass and appreciate the night sky. It's romantic, but... whenever I imagine all the bugs crawling all over me... Eww..."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_NORMAL_4"
L12_1 = "I'm from an aristocratic family. People from other countries tend to sneer for mentioning nobility in the 21st century, but... I don't mind. Ms. Aura said that the spirit it contains is more important than its symbolic meaning."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_LIFETIME_1"
L13_1 = "Uh... The way that I talked when I first met you? Well... I got inspired by books about knights that Ms. Aura recommended, and had this urge to leave a stunning impression... Could you please forget I ever did that?"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_LIFETIME_2"
L14_1 = "I originally wanted to become a ballerina. But I ended up quitting because I couldn't pay the tuition. It was for the best. Because now, I have a much better dream of saving the world with you by my side."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_LIFETIME_3"
L15_1 = "I wish I could leave Ms. Aura to handle all the conversations with strangers, but I think she wants me to get close to you. Plus, I don't mind talking with you."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_LIFETIME_4"
L16_1 = "Ms. Aura says that I look just like her back when she was alive. She said that her nickname was Bella Knight... Oh, Squire. It's not good for my heart if you suddenly stare at me like that... But, do I really look like her?"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_WORLDMAP_CHECK"
