L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_BLUE@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_BLUE_GET_01"
L13_1 = "Heard there's an evil spirit around. Need a hand? Exorcisms, holy water, prayers, you name it. Of course, it's not free. Nothing in this world is."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_BLUE@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_BLUE_LOBBY_CAPTAIN"
L14_1 = "I'm getting paid extra for this, right?"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_BLUE@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_BLUE_LOBBY_CONNECT"
L15_1 = "Oh, you're here? You know, evil spirits tend to latch onto valuables or anything pricey. So I just... checked. Not like I was gonna take anything. Nope, not at all."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_BLUE@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_BLUE_LOBBY_CONNECT_LIFETIME"
L16_1 = "I was waiting for you. Heard you coming from a mile away. Oh, and I happened to bring some monastery-brewed beer. Want some?"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_BLUE@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_BLUE_LOBBY_TOUCH_NORMAL_1"
L17_1 = "You're used to the taste of holy water? W-well, that's... good, I guess! Means the Lord's blessing is really working on you. So, while we're at it... why not grab a few more bottles? I'll talk to the Lord, maybe get you a discount."
L15_1[1] = L16_1
