L42_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_GET_01"
L43_1 = "I, Esterosa de Chevalier, Captain of the Zodiac Knights. Once more, I shall become your sword and shield, to protect the innocent. This vow shall never waver, so long as you and I still draw breath."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_CAPTAIN"
L44_1 = "I've received extensive training in tactics. Leave it to me without worry."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_CONNECT"
L45_1 = "Standing by. All clear. Awaiting your orders."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_CONNECT_LIFETIME"
L46_1 = "I've been waiting. Things just feel incomplete without you nearby."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_NORMAL_1"
L47_1 = "I used to see the Star Armament as nothing more than a symbol of the Order. But now, I understand. What I've inherited isn't just a sword. It's the pride of every knight who's wielded it before me."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_NORMAL_2"
L48_1 = "Whatever you seek, I will pursue. Whatever you desire, I will fight to obtain. I am your sword and shield. Everything I am is yours."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_NORMAL_3"
L49_1 = "The Red Shift situation has shaken the Order a bit, but it's all right. Deputy and others seem more motivated than ever, and with Dame Medea and Juli... ahem. Dame Leonhardt lending their strength, we'll be fine."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_NORMAL_4"
L50_1 = "The previous generation of the Zodiac Knights truly lived up to what people call the \"golden era.\" It's true that we, the current generation, fall short by comparison. But we have no intention of staying in their shadow forever."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_LIFETIME_1"
L51_1 = "I know that unleashing the Armament reflects the wielder's desires... B-but that doesn't mean I was imagining any specific outfit. An animal-themed pajama just happened to cross my mind by total coincidence."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_TOUCH_LIFETIME_2"
L52_1 = "I've carefully kept the sword and robe I used during my time of wandering. They're not hidden away, so Dame Liv or Dame Arius sometimes play around with them. When I see that... I find myself smiling the way she used to."
L50_1[1] = L51_1
L50_1[2] = L52_1
