L2_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW_LOBBY_TOUCH_NORMAL_1"
L3_1 = "The ignorants still believe the Order is a bastion of justice. But they're no different from the rest, blinded by their own greed. I've seen how fools like them meet their end."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW_LOBBY_TOUCH_NORMAL_2"
L4_1 = "Where are the other members, you ask? Hah. What a foolish question. Even if they serve the same faction, the only thing that moves them is their own selfish gain."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW_LOBBY_TOUCH_NORMAL_3"
L5_1 = "The kid... No, the current Captain of Blue Shift has earned the trust of quite a few. But as long as she carries Chevalier's bloodline... I can never acknowledge her."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW_LOBBY_TOUCH_NORMAL_4"
L6_1 = "Refusing to accept even a minor sacrifice is nothing but hypocrisy. Most people's convictions are just self-righteous indulgence in the name of justice. Without someone to make the hard choices, the world will stay trapped in the same cycle of contradiction."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW_LOBBY_TOUCH_LIFETIME_1"
L7_1 = "If Blue Shift's uniform symbolizes pure peace, then Red Shift's represents a will untouched by anything. The flower on my uniform stands for the conviction that's never once faltered."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW_LOBBY_TOUCH_LIFETIME_2"
L8_1 = "The former captain wasn't half bad. Skilled, respected, and strong in every field. But she was weak. That kindness of hers destroyed everything."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW_LOBBY_TOUCH_LIFETIME_3"
L9_1 = "The Sagittarius Armament has its proper uses. But unless the need is absolute, I keep its power sealed. Anyone who dares wield it must be prepared to bear the weight."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_C_ARROW_LOBBY_TOUCH_LIFETIME_4"
L10_1 = "We're not always on edge. Sometimes we sit down with tea and music, enjoy the quiet. Care to join me? Understanding you might prove useful down the line."
L8_1[1] = L9_1
L8_1[2] = L10_1
