L5_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ATELIER_C_TIMEBLADE@AB_UI_UNIT_VOICE_NKM_UNIT_ATELIER_C_TIMEBLADE_GET_01"
L6_1 = "I am Seosaeng. As it happens, I was just reviewing your research notes. Perhaps you'd care to offer your insights?"
