L22_1 = "SI_EXPLORE_RULE_1"
L23_1 = [[
<b><color=#FFD34C>[Great Expedition]</color></b>
<color=#FFFFFF>- Playable only during the event period. All progress resets once the event ends.</color>
<color=#FFFFFF>- Instead of using your existing squads, you begin with a preset formation and proceed using only the squads acquired during the expedition.</color>
<color=#FFFFFF>- You can check each stage's reward type and enemy roles, allowing you to strategize based on role advantages.</color>
<color=#FFFFFF>- Upon success or failure, all acquired squads and Artifacts are reset.</color>

<b><color=#FFD34C>[Great Expedition Season Enhancements]</color></b>
<color=#FFFFFF>- Earn Enhancement Points based on the area cleared when failing or completing an expedition.</color>
<color=#FFFFFF>- Use Enhancement Points on Season Enhancements. Enhanced stats can be reset at any time.</color>

<b><color=#FFD34C>[Great Expedition Score Rewards]</color></b>
<color=#FFFFFF>- Earn Reward Points based on the highest stage cleared during the event period.</color>
<color=#FFFFFF>- Redeem rewards with the points you have earned.</color>]]
L21_1[1] = L22_1
L21_1[2] = L23_1
