L7_1 = "Burnett... You still remember that name, Old Voice. But the man who bore it is long dead. I am the Knight of the Lake, Apostle of Mother Gha'agsheblah, guardian of the Lake of Knowledge."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_CA_KNIGHT_LOBBY_TOUCH_NORMAL_2"
L8_1 = "The Children of Yaldabaoth are a congregation gathered for Mother's manifestation. When the shattered Lake of Knowledge is made whole and the aimless Society cast aside, our sacred purpose will finally be fulfilled."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
