L9_1 = "Reborn under the Lake's blessing, I serve only Mother Gha'agsheblah's essence. Should you stand against her will, the Institution, the Society, and even you, Old Voice, are my enemies."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
