L10_1 = "In fragments of my memory, the daughter of the House Pendragon was smaller, more fragile. Yet the Pendragon of this world has grown into quite the bold young woman. Heh. How nostalgic."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
