L11_1 = "The Society has endured through countless names and forms. Yet now that it has abandoned its devotion to the Lake and lives only to serve one person, the Lake's blessing will surely side with us."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
