L12_1 = "Prydwen was the shield granted by the king. But I betrayed that trust and failed to protect anything. Perhaps it was my fate from the beginning to wield chains instead of a shield."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
