L13_1 = "Noblesse oblige. The Institution always forces contradictions upon individuals. Yet in the end, it merely mimics your way, Old Voice. And still, you refuse to give up."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
