L6_1 = {}
L7_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR_GET_01"
L8_1 = "Now that my memories have returned, I won't be needing those restraints anymore. ...Staring at me like that brings back old memories. I always found it irritating how you looked down on me like a child. I even thought I'd punch you for it one day. Now then, lower that stiff neck of yours."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR_LOBBY_CAPTAIN"
L9_1 = "Bring me a podium. Or I'll climb onto your shoulders instead."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR_LOBBY_CONNECT"
L10_1 = "You're here. Let's begin work."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR_LOBBY_CONNECT_LIFETIME"
L11_1 = "You kept me waiting. If you prefer, I'll come wake you tomorrow instead. And you will regret it."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR_LOBBY_TOUCH_NORMAL_1"
L12_1 = "Past memories? Yes, one comes to mind. You used to treat me like a child and mock me for it. You say you were just looking down on me, not mocking me? Hmph. Tall people never seem to realize those two are the same thing."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR_LOBBY_TOUCH_NORMAL_2"
L13_1 = "There was a time when I welcomed being called Master. That was before I realized I was using them for my own sake. The name Freyja as well... Now it's nothing more than a mark of shame."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR_LOBBY_TOUCH_NORMAL_3"
L14_1 = "People don't grow just because time passes. Growth comes from suppressing one's limits and tying them off by one's own hand. Proper nutrition comes after that."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR@AB_UI_UNIT_VOICE_NKM_UNIT_FENRIR_CA_HILDE_PR_LOBBY_TOUCH_NORMAL_4"
L15_1 = "Regin and Fafnir aren't wings. They're thorned shackles binding me in place. Well, they still serve to beat down nuisances, so the result is much the same."
L13_1[1] = L14_1
L13_1[2] = L15_1
