L45_1 = "AB_UI_UNIT_VOICE_OPR_CREW@AB_UI_UNIT_VOICE_OPR_CREW_GET_01"
L46_1 = "I learned to speak gently to keep my thirst for battle in check. But... I suppose I needn't bother with that in front of you, Captain. Fufu. So, where's the battlefield?"
L44_1[1] = L45_1
L44_1[2] = L46_1
