L46_1 = "AB_UI_UNIT_VOICE_OPR_CREW@AB_UI_UNIT_VOICE_OPR_CREW_LOBBY_CAPTAIN"
L47_1 = "I may have left piracy behind, but work like this is familiar. Leave it to me."
