L21_1 = {}
L22_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ANAPILIS_CA_SCYTHE@AB_UI_UNIT_VOICE_NKM_UNIT_ANAPILIS_CA_SCYTHE_LOBBY_TOUCH_NORMAL_1"
L23_1 = "Oh, a pretty flower has bloomed here. Then I'll gratefully enjoy it... It wasn't grown to be eaten? But isn't it a shame to let it wither and fall to the ground?"
