L22_1[2] = L24_1
L23_1 = {}
L24_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ANAPILIS_CA_SCYTHE@AB_UI_UNIT_VOICE_NKM_UNIT_ANAPILIS_CA_SCYTHE_LOBBY_TOUCH_NORMAL_3"
L25_1 = "If there's a Demon Lord who won't listen, please let me know. If talking doesn't work, I can give them a little knock on the head... Oh, don't worry. Something like that wouldn't make them disappear."
